void loop() {
  unsigned long now = millis();
  if (i == 0) {
    lcd.setCursor(0, 1);
    lcd.print("BOOM!");
  }
  if (now - prev >= 1000 && i > 0) {
    prev += 1000;
    lcd.setCursor(0, 1);
    lcd.print(i--);
  }
}

