char buf[16];
int n = 0;

void loop() {
  char c = Serial.read();
  if (c == '\n') {
    buf[n] = 0;
    handle(buf);
    n = 0;
  } else {
    buf[n++] = c;
  }
}

fix:
while (Serial.available() > 0) {
  char c = Serial.read();
  if (c == '\n') {
    buf[n] = 0;
    handle(buf);
    n = 0;
  } else if (n < sizeof buf - 1) {
    buf[n++] = c;
  }
}

